// commentPos reports the position in v of the start of an inline comment:
// a ';' or '#' at position 0 or preceded by whitespace. It returns -1 if
// there is none.
func commentPos(v string) int {
	for i, c := range v {
		if c != ';' && c != '#' {
			continue
		}
		if i == 0 || v[i-1] == ' ' || v[i-1] == '\t' {
			return i
		}
	}
	return -1
